from typing import Dict, List, Tuple, Optional

class TrieNode:
    """Represents a single node in the Trie."""
    def __init__(self):
        # Children mapping: character -> TrieNode
        self.children: Dict[str, 'TrieNode'] = {}
        # Data stored when this node marks the end of a word
        self.is_end_of_word: bool = False
        # Original spelling and weight (stored as tuple: (weight, original_spelling))
        self.word_data: Optional[Tuple[float, str]] = None

class Autocomplete:
    """A case-insensitive autocomplete service using a Trie structure."""
    def __init__(self):
        self.root = TrieNode()

    def add(self, word: str, weight: float = 1.0) -> None:
        """Stores a word with a given weight. Replaces if the casefolded form exists."""
        if not word:
            raise ValueError("Word cannot be empty.")

        cf_word = word.casefold()
        node = self.root

        for char in cf_word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]

        node.is_end_of_word = True
        # Replace existing word data if it matches the casefolded form
        node.word_data = (weight, word)

    def delete(self, word: str) -> bool:
        """Removes a word from the Trie based on its casefolded form."""
        if not word:
            return False

        cf_word = word.casefold()
        node = self.root
        path: List[Tuple[str, TrieNode]] = []

        # 1. Traverse to find the word node
        for char in cf_word:
            if char not in node.children:
                return False
            path.append((char, node))
            node = node.children[char]

        if not node.is_end_of_word or node.word_data is None:
            return False

        # 2. Remove word metadata
        node.is_end_of_word = False
        node.word_data = None

        # 3. Backtrack and prune unnecessary nodes
        # We prune if the node is no longer an end-of-word AND has no children
        for i in range(len(path) - 1, -1, -1):
            char, parent = path[i]
            child = parent.children[char]

            if child.is_end_of_word or child.children:
                # Stop pruning if this node is part of another word or has other branches
                break
            else:
                # Prune: remove the child link from the parent
                del parent.children[char]

        return True

    def __len__(self) -> int:
        """Returns the total number of stored words."""
        count = 0
        queue = [self.root]
        while queue:
            node = queue.pop(0)
            if node.is_end_of_word: # Check for word_data presence is safer but is_end_of_word implies it here
                count += 1
            for child in node.children.values():
                queue.append(child)
        return count

    def __contains__(self, word: str) -> bool:
        """Checks if a word with the given casefolded form is stored."""
        if not word:
            return False

        cf_word = word.casefold()
        node = self.root

        for char in cf_word:
            if char not in node.children:
                return False
            node = node.children[char]

        return node.is_end_of_word

    def complete(self, prefix: str, k: int = 10) -> List[str]:
        """Returns up to k suggested words starting with the given prefix, ordered by weight."""
        if k <= 0: 
            return []

        cf_prefix = prefix.casefold()
        node = self.root

        # 1. Traverse to the prefix node
        for char in cf_prefix:
            if char not in node.children:
                return [] # No words start with this prefix
            node = node.children[char]

        # 2. Collect all matching words (DFS/BFS traversal from this node)
        # Stores (weight, original_spelling) for all descendants that are terminal nodes
        results: List[Tuple[float, str]] = []
        stack: List[TrieNode] = [node]

        while stack:
            current_node = stack.pop()

            if current_node.is_end_of_word and current_node.word_data:
                weight, spelling = current_node.word_data
                results.append((weight, spelling))

            # Push children onto stack (order doesn't matter for collection)
            for child_node in current_node.children.values():
                stack.append(child_node)

        # 3. Sort: Primary key is weight (descending), secondary key is casefolded form (ascending)
        # Since we only stored the original spelling, we use its casefolded form for secondary sorting.
        def sort_key(item: Tuple[float, str]) -> Tuple[float, str]:
            weight, spelling = item
            return (-weight, spelling.casefold())

        results.sort(key=sort_key)

        # 4. Return top k original spellings
        return [spelling for _, spelling in results[:k]]

