        self.history: List[Tuple[str, str, str]] = []
        self._transitions: List[Transition] = transitions
        self._state_map: dict[str, Union[State, None]] = {}
        self._state_names: set[str] = set()
        self._listeners: List[Callable[[str, Event, str], Any]] = []
        self._is_firing = False
        self._initial_state_name = initial

        # 1. Process states and build state map
        state_names_set = set()
        for s in states:
            name = s.name if isinstance(s, State) else s
            if name in state_names_set:
                raise ValueError(f"Two states share the name: {name}")
            state_names_set.add(name)

            if isinstance(s, State):
                self._state_map[name] = s
            else:
                self._state_map[name] = None # Plain name

        # 2. Validation checks
        if not states:
            raise ValueError("States list cannot be empty.")

        if initial not in state_names_set:
            raise ValueError(f"Initial state '{initial}' is not a defined state.")

        # 3. Validate transitions against defined states
        all_state_names = state_names_set
        for t in transitions:
            # Validate source
            valid_source = False
            if t.source == '*':
                valid_source = True
            elif isinstance(t.source, str) and t.source in all_state_names:
                valid_source = True
            elif isinstance(t.source, (list, tuple)) and all(s in all_state_names for s in t.source):
                valid_source = True

            if not valid_source:
                 raise ValueError(f"Transition event '{t.event}' names an invalid source: {t.source}")

            # Validate target
            if t.target is not None:
                if t.target not in all_state_names:
                    raise ValueError(f"Transition event '{t.event}' names an invalid target: {t.target}")

        # 4. Initialize state
        self.state = initial
        self.history.append((None, None, None)) # Sentinel for initial state setup if needed, though spec says constructor runs no hooks

    @property
    def state(self) -> str:
        return self._state

    @state.setter
    def state(self, new_state_name: str):
        if self._is_firing:
            raise MachineError("Cannot change state while a fire operation is in progress.")
        self._state = new_state_name

    def _execute_hook(self, hook: Callable[[Machine], Any], event: Event, is_exit: bool = False) -> Any: 
        """Helper to execute hooks and handle propagation."""
        try:
            return hook(self)
        except Exception as e:
            # Exception propagates unchanged out of fire if it's from a guard, on_exit, or action
            # If it comes from on_enter or a listener, the state has already changed, so it propagates out.
            raise e

    def fire(self, event_name: str, **data) -> str:
        if self._is_firing:
            raise MachineError("Cannot fire on a machine while one of its fire calls is still running.")
        self._is_firing = True

        current_state_name = self.state
        event_data = data.copy()
        event_payload = Event(name=event_name, source=current_state_name, target="", data=event_data)

        # 1. Find candidates
        candidates = []
        for t in self._transitions:
            if t.event != event_name: 
                continue

            source_matches = False
            if t.source == '*':
                source_matches = True
            elif isinstance(t.source, str) and t.source == current_state_name:
                source_matches = True
            elif isinstance(t.source, (list, tuple)) and current_state_name in t.source:
                source_matches = True

            if source_matches: 
                candidates.append(t)

        if not candidates:
            self._is_firing = False
            raise InvalidTransition(state=current_state_name, event=event_name)

        # 2. Create data dict (already handled by event_data)

        # 3. Evaluate guards
        selected_transition: Optional[Transition] = None
        for candidate in candidates:
            if candidate.guard is None:
                selected_transition = candidate
                break
            try:
                # Guards must not have side effects
                if candidate.guard(self):
                    selected_transition = candidate
                    break
            except Exception: # Treat any exception in guard as a rejection if it's not a clear success
                pass # Move to next candidate if guard fails/raises

        if selected_transition is None:
            self._is_firing = False
            raise GuardRejected(state=current_state_name, event=event_name)

        # 4. Execute transition logic
        transition = selected_transition
        target_state_name = transition.target
        is_internal = target_state_name is None

        # --- State Change Sequence ---
        if not is_internal:
            # Normal transition
            try:
                # a. Current state's on_exit
                if self._state_map[current_state_name] and self._state_map[current_state_name].on_exit:
                    self._execute_hook(self._state_map[current_state_name].on_exit, event_payload, is_exit=True)

                # b. Transition's action
                if transition.action:
                    self._execute_hook(transition.action, event_payload)

                # c. Set state and record history
                old_state = self.state
                self.state = target_state_name
                self.history.append((old_state, event_name, target_state_name if target_state_name is not None else old_state))

                # d. Target state's on_enter
                if self._state_map[target_state_name] and self._state_map[target_state_name].on_enter:
                    self._execute_hook(self._state_map[target_state_name].on_enter, event_payload)

            except Exception: # If exception occurs in exit/action/enter, state/history are potentially unchanged or the exception propagates
                self._is_firing = False
                raise
        else: 
            # Internal transition
            try:
                # a. Only run action
                if transition.action:
                    self._execute_hook(transition.action, event_payload)

                # b. Record history (target == source)
                self.history.append((current_state_name, event_name, current_state_name))
            except Exception:
                self._is_firing = False
                raise

        # 5. Run listeners
        try:
            for listener in self._listeners:
                # Listeners are called after state change (if any)
                listener(current_state_name, event_payload, target_state_name if target_state_name is not None else current_state_name)
        except Exception:
            # Exception from listener propagates
            self._is_firing = False
            raise

        self._is_firing = False
        return self.state

    def can_fire(self, event_name: str, **data) -> bool:
        current_state_name = self.state

        # 1. Find candidates
        candidates = []
        for t in self._transitions:
            if t.event != event_name: 
                continue

            source_matches = False
            if t.source == '*':
                source_matches = True
            elif isinstance(t.source, str) and t.source == current_state_name:
                source_matches = True
            elif isinstance(t.source, (list, tuple)) and current_state_name in t.source:
                source_matches = True

            if source_matches: 
                candidates.append(t)

        if not candidates:
            return False

        # 2. Evaluate guards
        for candidate in candidates:
            if candidate.guard is None:
                return True # Found one with no guard
            try:
                # Must not have side effects
                if candidate.guard(self):
                    return True # Found one with a truthy guard
            except Exception:
                # Treat any exception as rejection for can_fire
                pass

        return False

    def available_events(self) -> List[str]:
        current_state_name = self.state
        events = set()
        for t in self._transitions:
            if t.source == '*':
                events.add(t.event)
                continue

            if isinstance(t.source, str) and t.source == current_state_name:
                events.add(t.event)
            elif isinstance(t.source, (list, tuple)) and current_state_name in t.source:
                events.add(t.event)
        return sorted(list(events))

    def on_transition(self, listener: Callable[[str, Event, str], Any]):
        self._listeners.append(listener)

    def reset(self):
        self._state = self._initial_state_name
        self.history = []

    # Public property for state access, although it's a setter/getter combo above, keeping it explicit
    @property
    def _state(self):
        return self.state
