## Define Formula AST Structures

from typing import Union, List, Set, Any
import re

class FormulaError(ValueError):
    """Raised when a formula is syntactically invalid or refers to an invalid cell."""
    pass

class ErrorValue(str):
    """Represents an error value in a cell."""
    pass

# --- AST Node Definitions ---

class ASTNode:
    """Base class for all AST nodes."""
    pass

class BinaryOp(ASTNode):
    """Represents a binary operation: left_operand OP right_operand."""
    def __init__(self, left: ASTNode, op: str, right: ASTNode):
        self.left = left
        self.op = op  # '+', '-', '*', '/'
        self.right = right

    def __repr__(self):
        return f"BinaryOp({self.left!r}, '{self.op}', {self.right!r})"

class UnaryOp(ASTNode):
    """Represents a unary operation: OP operand."""
    def __init__(self, op: str, operand: ASTNode):
        self.op = op  # '+', '-'
        self.operand = operand

    def __repr__(self):
        return f"UnaryOp('{self.op}', {self.operand!r})"

class Number(ASTNode):
    """Represents a numeric literal."""
    def __init__(self, value: Union[int, float]):
        self.value = value

    def __repr__(self):
        return f"Number({self.value})"

class Ref(ASTNode):
    """Represents a cell reference (e.g., 'A1')."""
    def __init__(self, name: str):
        self.name = name.upper()

    def __repr__(self):
        return f"Ref('{self.name}')"

class ParenExpression(ASTNode):
    """Represents an expression enclosed in parentheses."""
    def __init__(self, expression: ASTNode):
        self.expression = expression

    def __repr__(self):
        return f"ParenExpression({self.expression!r})"

# --- Tokenizer and Parser ---

class Token:
    """Represents a lexical token."""
    def __init__(self, type: str, value: Any = None):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {repr(self.value)})"

TOKEN_SPECIFICATION = [ 
    ('NUMBER', r'[0-9]+(\.[0-9]+)?'),
    ('REF', r'[a-zA-Z]+[0-9]+'),  # Letters followed by digits
    ('PLUS', r'\+'),
    ('MINUS', r'\-'),
    ('MUL', r'\*'),
    ('DIV', r'\/'),
    ('LPAREN', r'\('),
    ('RPAREN', r'\)'),
    ('SKIP', r'[ \t\r]+')  # Whitespace
]

class Lexer:
    """Tokenizes the formula string."""
    def __init__(self, text: str):
        self.text = text
        self.tokens: List[Token] = []
        self._tokenize()

    def _tokenize(self):
        token_regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in TOKEN_SPECIFICATION)
        for mo in re.finditer(token_regex, self.text): 
            kind = mo.lastgroup
            value = mo.group(kind) 

            if kind == 'SKIP':
                continue

            elif kind == 'NUMBER':
                try:
                    if '.' in value:
                        self.tokens.append(Token('NUMBER', float(value)))
                    else:
                        self.tokens.append(Token('NUMBER', int(value)))
                except ValueError:
                    # Should not happen with the regex, but good practice
                    raise FormulaError(f"Invalid number format: {value}")

            elif kind == 'REF':
                self.tokens.append(Token('REF', value))

            elif kind in ('PLUS', 'MINUS', 'MUL', 'DIV', 'LPAREN', 'RPAREN'):
                self.tokens.append(Token(kind, value))

            else:
                # Fallback for unrecognized characters
                raise FormulaError(f"Illegal character in formula: {value}")

    def get_tokens(self) -> List[Token]:
        return self.tokens

class Parser:
    """Parses the token stream into an AST."""
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else Token('EOF')

    def consume(self, expected_type: str = None) -> Token:
