# Helper functions for evaluation logic
def _get_lookup_value(value: Any) -> Union[int, float, str]:
    """Converts cell value to a usable type for arithmetic or returns it as a string if text."""
    if isinstance(value, (int, float)):
        return value
    if isinstance(value, ErrorValue):
        return value
    # Text values are returned as is, they will cause #ERROR! if used in arithmetic
    return str(value)

def _handle_error(e: Union[ErrorValue, type(None)]) -> Union[ErrorValue, int, float]:
    """Handles error propagation based on spreadsheet rules."""
    if isinstance(e, ErrorValue):
        # If the error is already an ErrorValue, propagate it
        return e
    # If the input was None (empty cell), treat it as 0 in calculations (Rule 2, point 2)
    if e is None:
        return 0
    # Any other unexpected non-error/non-None input during calculation should ideally not happen
    # but we default to a generic calculation error if it does.
    return ErrorValue("#ERROR!")

# Function to extract all cell references
def references(tree: ASTNode) -> Set[str]:
    """Recursively traverses the AST to find all unique cell references."""
    references_set = set()

    if isinstance(tree, Ref):
        references_set.add(tree.name)
    elif isinstance(tree, BinaryOp):
        references_set.update(references(tree.left))
        references_set.update(references(tree.right))
    elif isinstance(tree, UnaryOp):
        references_set.update(references(tree.operand))
    elif isinstance(tree, ParenExpression):
        references_set.update(references(tree.expression))
    # Number nodes do not contain references

    return references_set

# Function to evaluate the AST
def evaluate(tree: ASTNode, lookup: Callable[[str], Any]) -> Union[int, float, str]:
    """Computes the formula's value recursively using the provided lookup function."""

    if isinstance(tree, Number):
        return tree.value

    if isinstance(tree, Ref):
        value = lookup(tree.name)
        # Rule 2: A reference gives the cell's value, except that an empty cell (None) gives 0.
        if value is None:
            return 0
        # Rule 2 (cont.): If the result is text, return text unchanged.
        if isinstance(value, str) and not value.isdigit() and '.' not in value:
            return value # Return text value directly if it's not just a number representation
        return value

    if isinstance(tree, UnaryOp):
        operand_value = evaluate(tree.operand, lookup)
        # Rule 3: If an operand is an error value, the result is that error value (the left one if both are).
        if isinstance(operand_value, ErrorValue):
            return operand_value

        # Apply unary sign
        if tree.op == '+':
            return _handle_error(operand_value)
        if tree.op == '-':
            if isinstance(operand_value, (int, float)):
                return _handle_error(operand_value) * -1
            # If operand is text, subtraction results in #ERROR!
            return ErrorValue("#ERROR!")

    if isinstance(tree, BinaryOp):
        left_value = evaluate(tree.left, lookup)
        right_value = evaluate(tree.right, lookup)

        # Rule 3: Error propagation
        if isinstance(left_value, ErrorValue) or isinstance(right_value, ErrorValue):
            return left_value if isinstance(left_value, ErrorValue) else right_value

        # Rule 3: Text handling
        if isinstance(left_value, str) and not isinstance(left_value, ErrorValue) and 
           isinstance(right_value, str) and not isinstance(right_value, ErrorValue):
            return ErrorValue("#ERROR!")

        # Handle numeric operations
        try:
            left_num = _get_lookup_value(left_value)
            right_num = _get_lookup_value(right_value)

            if tree.op == '+':
                return left_num + right_num
            elif tree.op == '-':
                return left_num - right_num
            elif tree.op == '*':
                return left_num * right_num
            elif tree.op == '/':
                # Rule 3: Division by zero gives #ERROR!
                if right_num == 0:
                    return ErrorValue("#ERROR!")
                # Rule 3: Division always gives a float
                return float(left_num) / float(right_num)
        except TypeError:
            # Catch cases where mixed types (e.g., str and int) are encountered in math where they shouldn't be.
            return ErrorValue("#ERROR!")

    # Should be unreachable if AST is complete
    return ErrorValue("#ERROR!")

