# --- Tokenizer and Parser ---

class Token:
    """Represents a lexical token."""
    def __init__(self, type: str, value: Any = None):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {repr(self.value)})"

TOKEN_SPECIFICATION = [
    ('NUMBER', r'[0-9]+(\.[0-9]+)?'),
    ('REF', r'[a-zA-Z]+[0-9]+'),  # Letters followed by digits
    ('PLUS', r'\+'),
    ('MINUS', r'\-'),
    ('MUL', r'\*'),
    ('DIV', r'\/'),
    ('LPAREN', r'\('),
    ('RPAREN', r'\)'),
    ('SKIP', r'[ \t\r]+')  # Whitespace
]

class Lexer:
    """Tokenizes the formula string."""
    def __init__(self, text: str):
        self.text = text
        self.tokens: List[Token] = []
        self._tokenize()

    def _tokenize(self):
        token_regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in TOKEN_SPECIFICATION)
        for mo in re.finditer(token_regex, self.text): 
            kind = mo.lastgroup
            value = mo.group(kind) 

            if kind == 'SKIP':
                continue

            elif kind == 'NUMBER':
                try:
                    if '.' in value:
                        self.tokens.append(Token('NUMBER', float(value)))
                    else:
                        self.tokens.append(Token('NUMBER', int(value)))
                except ValueError:
                    raise FormulaError(f"Invalid number format: {value}")

            elif kind == 'REF':
                self.tokens.append(Token('REF', value))

            elif kind in ('PLUS', 'MINUS', 'MUL', 'DIV', 'LPAREN', 'RPAREN'):
                self.tokens.append(Token(kind, value))

            else:
                raise FormulaError(f"Illegal character in formula: {value}")

    def get_tokens(self) -> List[Token]:
        return self.tokens

class Parser:
    """Parses the token stream into an AST."""
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else Token('EOF')

    def consume(self, expected_type: str = None) -> Token:
        token = self.current_token()
        if expected_type and token.type != expected_type:
            raise FormulaError(f"Expected {expected_type} but found {token.type} with value {token.value}")
        self.pos += 1
        return token

    def parse(self) -> ASTNode:
        ast = self.expr()
        if self.current_token().type != 'EOF':
            raise FormulaError("Unexpected tokens remaining after parsing complete.")
        return ast

    # Grammar rules implemented via precedence climbing / recursive descent

    # expr := term {(+ | -) term}
    def expr(self) -> ASTNode:
        node = self.term()
        while self.current_token().type in ('PLUS', 'MINUS'):
            op_token = self.consume()
            right = self.term()
            node = BinaryOp(node, op_token.type.replace('PLUS', '+').replace('MINUS', '-'), right)
        return node

    # term := unary {(* | /) unary}
    def term(self) -> ASTNode:
        node = self.unary()
        while self.current_token().type in ('MUL', 'DIV'):
            op_token = self.consume()
            right = self.unary()
            node = BinaryOp(node, op_token.type.replace('MUL', '*').replace('DIV', '/'), right)
        return node

    # unary := (+ | -) unary | number | ref | ( expr )
    def unary(self) -> ASTNode:
        token = self.current_token()

        # Unary sign check (must be followed by another unary/value)
        if token.type in ('PLUS', 'MINUS'):
            op_token = self.consume()
            operand = self.unary()
            return UnaryOp(op_token.type.replace('PLUS', '+').replace('MINUS', '-'), operand)

        # Handle parentheses
        elif token.type == 'LPAREN':
            self.consume('LPAREN')
            node = self.expr()
            self.consume('RPAREN')
            return ParenExpression(node)

        # Handle literals and references
        elif token.type == 'NUMBER':
            self.consume('NUMBER')
            return Number(token.value)

        elif token.type == 'REF':
            self.consume('REF')
            return Ref(token.value)

        else:
            raise FormulaError(f"Unexpected token where unary expression expected: {token.type} ({token.value})")


def parse_formula(source: str) -> ASTNode:
    """Parses the text after '=' and returns a syntax tree. Raises FormulaError on failure."""
    if not source.strip():
        raise FormulaError("Formula input cannot be empty.")

    # Tokenize, handling whitespace
    lexer = Lexer(source)
    tokens = lexer.get_tokens()

    # Parse the token stream
    parser = Parser(tokens)
    return parser.parse()

# --- Formula Utilities ---

# Helper functions for evaluation logic
def _get_lookup_value(value: Any) -> Union[int, float, str]:
    """Converts cell value to a usable type for arithmetic or returns it as a string if text."""
    if isinstance(value, (int, float)):
        return value
    if isinstance(value, ErrorValue):
        return value
    # Text values are returned as is, they will cause #ERROR! if used in arithmetic
    return str(value)

def _handle_error(e: Union[ErrorValue, type(None)]) -> Union[ErrorValue, int, float]:
    """Handles error propagation based on spreadsheet rules."""
    if isinstance(e, ErrorValue):
        # If the error is already an ErrorValue, propagate it
        return e
    # If the input was None (empty cell), treat it as 0 in calculations (Rule 2, point 2)
    if e is None:
        return 0
    # Catch anything else that sneaks through unexpectedly
    return ErrorValue("#ERROR!")

# Function to extract all cell references
def references(tree: ASTNode) -> Set[str]:
    """Recursively traverses the AST to find all unique cell references."""
    references_set = set()

    if isinstance(tree, Ref):
        references_set.add(tree.name)
    elif isinstance(tree, BinaryOp):
        references_set.update(references(tree.left))
        references_set.update(references(tree.right))
    elif isinstance(tree, UnaryOp):
        references_set.update(references(tree.operand))
    elif isinstance(tree, ParenExpression):
        references_set.update(references(tree.expression))
    # Number nodes do not contain references

    return references_set

# Function to evaluate the AST
def evaluate(tree: ASTNode, lookup: Callable[[str], Any]) -> Union[int, float, str]:
    """Computes the formula's value recursively using the provided lookup function."""

    if isinstance(tree, Number):
        return tree.value

    if isinstance(tree, Ref):
        value = lookup(tree.name)
        # Rule 2: A reference gives the cell's value, except that an empty cell (None) gives 0.
        if value is None:
            return 0
        # Rule 2 (cont.): If the result is text, return text unchanged.
        # We check if it looks like pure text (not just digits/float representation)
        if isinstance(value, str) and not value.replace('.', '', 1).isdigit():
            return value 
        return value

    if isinstance(tree, UnaryOp):
        operand_value = evaluate(tree.operand, lookup)
        # Rule 3: If an operand is an error value, the result is that error value.
        if isinstance(operand_value, ErrorValue):
            return operand_value

        # Apply unary sign
        if tree.op == '+':
            return _handle_error(operand_value)
        if tree.op == '-':
            if isinstance(operand_value, (int, float)):
                return _handle_error(operand_value) * -1
            # If operand is text, subtraction results in #ERROR!
            return ErrorValue("#ERROR!")

    if isinstance(tree, BinaryOp):
        left_value = evaluate(tree.left, lookup)
        right_value = evaluate(tree.right, lookup)

        # Rule 3: Error propagation
        if isinstance(left_value, ErrorValue) or isinstance(right_value, ErrorValue):
            return left_value if isinstance(left_value, ErrorValue) else right_value

        # Rule 3: Text handling (if both results are non-error strings)
        is_left_str = isinstance(left_value, str) and not isinstance(left_value, ErrorValue)
        is_right_str = isinstance(right_value, str) and not isinstance(right_value, ErrorValue)
        if is_left_str and is_right_str:
            return ErrorValue("#ERROR!")

        # Handle numeric operations
        try:
            left_num = _get_lookup_value(left_value)
            right_num = _get_lookup_value(right_value)

            if tree.op == '+':
                return left_num + right_num
            elif tree.op == '-':
                return left_num - right_num
            elif tree.op == '*':
                return left_num * right_num
            elif tree.op == '/':
                # Rule 3: Division by zero gives #ERROR!
                if right_num == 0:
                    return ErrorValue("#ERROR!")
                # Rule 3: Division always gives a float
                return float(left_num) / float(right_num)
        except TypeError:
            # Catch cases where mixed types (e.g., str and int) are encountered in math where they shouldn't be.
            return ErrorValue("#ERROR!")

    return ErrorValue("#ERROR!")
