                return left_num - right_num
            elif tree.op == '*':
                return left_num * right_num
            elif tree.op == '/':
                # Rule 3: Division by zero gives #ERROR!
                if right_num == 0:
                    return ErrorValue("#ERROR!")
                # Rule 3: Division always gives a float
                return float(left_num) / float(right_num)
        except TypeError:
            # Catch cases where mixed types (e.g., str and int) are encountered in math where they shouldn't be.
            return ErrorValue("#ERROR!")

    return ErrorValue("#ERROR!")

