# --- Constants and Helpers ---

MAX_COL = 26  # A-Z
MAX_ROW = 999

def _col_to_int(col: str) -> int: # A=0, B=1, ..., Z=25
    return ord(col.upper()) - ord('A')

def _int_to_col(i: int) -> str:
    return chr(ord('A') + i)

def _parse_cell_name(name: str) -> Tuple[int, int]:
    """Parses 'A1' into (col_index, row_index). Returns (-1, -1) if invalid."""
    if not name or not name[0].isalpha() or not name[1:].isdigit():
        return (-1, -1)

    col_str = name[0].upper()
    row_str = name[1:]

    if len(col_str) > 1: # Check for multi-letter columns (e.g., AA1)
        return (-1, -1)

    try:
        row_int = int(row_str)
        # Check for leading zeros in row numbers (e.g., A01 is invalid)
        if len(row_str) > 1 and row_str[0] == '0': 
             return (-1, -1)
        if not (1 <= row_int <= MAX_ROW):
             return (-1, -1)
    except ValueError:
        return (-1, -1)

    col_int = _col_to_int(col_str)
    if not (0 <= col_int < MAX_COL):
        return (-1, -1)

    return (col_int, row_int)

def _cell_to_name(col_int: int, row_int: int) -> str:
    """Converts (col_index, row_index) to uppercase cell name (e.g., 'B7')."""
    return f"{_int_to_col(col_int)}{row_int}"

def _row_major_sort_key(name: str) -> Tuple[int, int]:
    """Returns key for row-major sorting: (row, col)."""
    col_int, row_int = _parse_cell_name(name)
    if col_int == -1: # Should not happen if used correctly on valid cells
        return (float('inf'), float('inf'))
    return (row_int, col_int)

# --- Sheet Class Implementation ---

class Sheet:
    """Represents the spreadsheet engine."""
    def __init__(self):
        # Maps cell_name (str, uppercase) -> State object
        # State structure: {'raw': str, 'value': Any, 'formula': ASTNode | None, 'is_formula': bool}
        self.cells: Dict[str, Dict[str, Any]] = {}
        self.graph = DependencyGraph()
        self.evaluations: int = 0

    def _validate_name(self, name: str):
        """Raises ValueError if name is outside bounds."""
        col_int, row_int = _parse_cell_name(name)
        if col_int == -1 or row_int == -1 or not (0 <= col_int < MAX_COL and 1 <= row_int <= MAX_ROW):
            raise ValueError(f"Cell name '{name}' is outside the valid range (A1:Z999).")

    def _get_cell_state(self, name: str) -> Dict[str, Any]:
        """Retrieves or initializes the state for a cell name."""
        if name not in self.cells:
            self.cells[name] = {
                'raw': '', 
                'value': None, 
                'formula': None, 
                'is_formula': False
            }
        return self.cells[name]

    def get(self, name: str) -> Any:
        """Returns the cell's current computed value."""
        self._validate_name(name)
        return self.cells[name]['value']

    def raw(self, name: str) -> str:
        """Returns the input last stored."""
        self._validate_name(name)
        return self.cells[name]['raw']

    def cells(self) -> List[str]:
        """Returns the non-empty cells in row-major order."""
        non_empty_cells = [n for n, state in self.cells.items() if state['raw'].strip() != '']
        return sorted(non_empty_cells, key=_row_major_sort_key)

    def set(self, name: str, raw_input: str) -> List[str]:
        """Stores the cell's input, triggers recalculation, and returns affected cells in row-major order."""
        self._validate_name(name)
        name = name.upper()
        state = self._get_cell_state(name)

        # 1. Check if the cell's raw input is actually changing
        if state['raw'] == raw_input:
            return []

        # 2. Determine new state based on raw_input
        new_formula: ASTNode = None
        is_formula = False
        new_value: Any = None

        # Rule: '' empties the cell.
        if raw_input.strip() == '':
            new_value = None
            state['formula'] = None
            state['is_formula'] = False

        # Rule: Number check (optional - followed by digits/float)
        elif re.fullmatch(r'^[+-]? ([0-9]+(\.[0-9]*)?|[0-9]*\.?[0-9]+)$', raw_input.strip()):
            try:
                # Use float conversion and then check if it's effectively an integer
                val = float(raw_input.strip())
                new_value = int(val) if val == int(val) else val
                state['formula'] = None
                state['is_formula'] = False
            except ValueError:
                # Should be caught by regex, but defensive
                pass 

        # Rule: Formula check
        elif raw_input.strip().startswith('='):
            is_formula = True
            formula_source = raw_input.strip()[1:].strip()
            try:
                new_formula = parse_formula(formula_source)
                state['formula'] = new_formula
                state['is_formula'] = True

                # Extract dependencies immediately for graph setup
                precedents = references(new_formula)
                self.graph.set_dependencies(name, precedents)

            except FormulaError as e:
                # If parse fails, re-raise and leave sheet unchanged
                raise e

        # Rule: Text
        else:
            new_value = raw_input # Stored exactly as given, spaces included
            state['formula'] = None
            state['is_formula'] = False

        # Update the cell's raw input immediately (even if value is not finalized yet)
        state['raw'] = raw_input

        # 3. Determine affected cells
        # The cell itself + every cell that refers to it (direct or indirect)
        affected_names = self.graph.all_dependents(name)
        affected_names.add(name)

        # 4. Recalculation Phase

        # Update the current cell's immediate state based on input
        if new_value is not None: 
            state['value'] = new_value

        # We must re-evaluate all dependents, but in dependency order.
        # The set of cells to evaluate includes 'name' and all its dependents.
        cells_to_evaluate = sorted(list(affected_names), key=_row_major_sort_key)

        # Re-evaluate every cell that might have changed value or depended on a changed value
        for current_cell_name in cells_to_evaluate:
            current_state = self.cells[current_cell_name]

            if not current_state['is_formula'] or current_state['raw'].strip() == '':
                # Not a formula cell, or it's now empty.
                if current_state['raw'].strip() == '':
                     current_state['value'] = None
                continue

            # Check for cycle status
            if current_cell_name in self.graph.cycle_cells():
                current_state['value'] = ErrorValue("#CYCLE!")
                continue

            # Evaluate only if it's not a cycle cell
            try:
                # The lookup function must read the *current* state of all cells.
                lookup = lambda n: self.get(n) if n in self.cells and self.cells[n]['raw'].strip() != '' else None

                new_computed_value = evaluate(current_state['formula'], lookup)

                # Update the value
                current_state['value'] = new_computed_value

                # Rule: evaluations grows by exactly that number (i.e., 1 per formula cell evaluated successfully).
                # We count it if it successfully computes a non-error value.
                if isinstance(new_computed_value, (int, float, str)) and not isinstance(new_computed_value, ErrorValue):
                    self.evaluations += 1

            except Exception as e: # Catch potential runtime errors during evaluation
                current_state['value'] = ErrorValue("#ERROR!")

        # Return affected cells sorted by row-major order
        return sorted(list(affected_names), key=_row_major_sort_key)

