# Assuming Version and Range are defined in resolve/versions.py
from resolve.versions import Version, Range

class PackageIndex:
    """Central repository of all package metadata."""
    def __init__(self):
        # Structure: {name: {version_object: {dep_name: Range_object, ...}}}
        self._releases: Dict[str, Dict[Version, Dict[str, Range]]] = {}
        self._lock = threading.RLock()  # Ensure thread-safe additions

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None) -> None:
        """Adds a release for a package."""
        try:
            version = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Invalid version string '{version_str}' for {name}: {e}")

        if requires is None:
            requires = {}

        with self._lock:
            if name not in self._releases:
                self._releases[name] = {}

            if version in self._releases[name]:
                raise ValueError(f"Duplicate entry for {name}@{version_str} found during addition.")

            # Validate all required ranges
            validated_ranges = {}
            for dep_name, spec in requires.items():
                try:
                    validated_ranges[dep_name] = Range(spec)
                except ValueError as e:
                    raise ValueError(f"Invalid requirement spec '{spec}' for {name}@{version_str}: {e}")

            self._releases[name][version] = validated_ranges

    def versions(self, name: str) -> List[Version]:
        """Returns the list of known Version objects for a package, newest first."""
        with self._lock:
            if name not in self._releases:
                return []

            # Sort by Version object comparison (descending)
            return sorted(self._releases[name].keys(), reverse=True)

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        """Returns a dict mapping dependency names to their Range for a given Version."""
        with self._lock:
            if name not in self._releases:
                raise KeyError(f"Package {name} not found in index.")

            version_releases = self._releases[name]
            if version not in version_releases:
                raise KeyError(f"Version {version} of {name} not found in index.")

            return version_releases[version]

    @classmethod
    def from_dict(cls, data: Dict[str, Dict[str, Dict[str, str]]]) -> 'PackageIndex':
        """Builds an index from a structured dictionary input."""
        index = cls()
        for name, versions_data in data.items():
            for version_str, requires_data in versions_data.items():
                try:
                    version = Version(version_str)
                except ValueError as e:
                    # Skip entries with bad versions, or raise if strictness requires it
                    print(f"Warning: Skipping entry {name}@{version_str} due to invalid version: {e}")
                    continue

                # Convert spec strings to Range objects
                validated_ranges = {}
                for dep_name, spec in requires_data.items():
                    try:
                        validated_ranges[dep_name] = Range(spec)
                    except ValueError as e:
                        print(f"Warning: Skipping dependency {dep_name} for {name}@{version_str} due to invalid spec: {e}")
                        continue

                # Use the internal _add logic safely for bulk loading
                index._add_release_internal(name, version, validated_ranges)

        return index

    # Internal method to bypass external checks during bulk load
    def _add_release_internal(self, name: str, version: Version, ranges: Dict[str, Range]):
        with self._lock:
            if name not in self._releases:
                self._releases[name] = {}
            self._releases[name][version] = ranges


