import re
from functools import total_ordering
from typing import List, Dict, Union

# --- Version Class ---

@total_ordering
class Version:
    """Represents a semantic version MAJOR.MINOR.PATCH."""
    def __init__(self, text: str):
        parts = text.split('.')
        if len(parts) != 3:
            raise ValueError(f"Version '{text}' must have three parts (MAJOR.MINOR.PATCH).")

        major_str, minor_str, patch_str = parts

        def parse_part(s: str, name: str) -> int:
            # Strict validation: digits only, no leading zeros unless the value is '0'
            if not s.isdigit():
                raise ValueError(f"Version part '{s}' in {name} contains non-digit characters.")
            if len(s) > 1 and s.startswith('0'):
                raise ValueError(f"Version part '{s}' in {name} has a leading zero.")
            return int(s)

        try:
            self.major = parse_part(major_str, "major")
            self.minor = parse_part(minor_str, "minor")
            self.patch = parse_part(patch_str, "patch")
        except ValueError as e:
            raise ValueError(f"Invalid version format in '{text}': {e}")

    @property
    def major(self) -> int:
        return self._major

    @property
    def minor(self) -> int:
        return self._minor

    @property
    def patch(self) -> int:
        return self._patch

    def __hash__(self) -> int:
        return hash((self.major, self.minor, self.patch))

    def __eq__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major == other.major and
                self.minor == other.minor and
                self.patch == other.patch)

    def __repr__(self) -> str:
        return f"Version('{self.to_text()}')"

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __le__(self, other):
        return self < other or self == other

    def __gt__(self, other):
        return not (self <= other)

    def __ge__(self, other):
        return not (self < other)

    def to_text(self) -> str:
        return f"{self.major}.{self.minor}.{self.patch}"

    def __str__(self) -> str:
        return self.to_text()

# Helper function to parse version text into a Version object
def parse_version(text: str) -> Version:
    return Version(text)


# --- Range Class ---

class Range:
    """Represents a version range specification."""
    def __init__(self, spec: str):
        self._original_spec = spec
        self.constraints: List[tuple[str, Union[Version, None]]] = []
        self._parse_spec(spec)

    def _parse_spec(self, spec: str):
        constraint_specs = [c.strip() for c in spec.split(',') if c.strip()]

        for cs in constraint_specs:
            cs = cs.strip()
            if not cs: continue

            # Check for prefixes first (^, ~)
            if cs.startswith('^'):
                self.constraints.append((cs, None)) # Store prefix as operator
                continue
            if cs.startswith('~'):
                self.constraints.append((cs, None)) # Store prefix as operator
                continue

            # Check for operators (>=, <=, !=, >, <, ==)
            op_map = {'==': '==', '!=': '!=', '>=': '>=', '<=': '<=', '>': '>', '<': '<'}
            found_op = False
            for op_str in sorted(op_map.keys(), key=len, reverse=True):
                if cs.startswith(op_str):
                    op_name = op_str
                    v_str = cs[len(op_str):].strip()
                    try:
                        version = parse_version(v_str)
                        self.constraints.append((op_name, version))
                        found_op = True
                        break
                    except ValueError:
                        raise ValueError(f"Bad version '{v_str}' in constraint '{cs}'")

            if not found_op:
                # Must be wildcard or exact match
                if cs == '*':
                    self.constraints.append(('*', None))
                else:
                    # Assume exact match
                    try:
                        version = parse_version(cs)
                        self.constraints.append(('==', version))
                    except ValueError:
                        raise ValueError(f"Bad version '{cs}' in constraint '{cs}'")

    def contains(self, v: Version) -> bool:
        """Checks if a Version object satisfies all constraints in this Range."""
        for op, target_v in self.constraints:
            if op == '*':
                continue
            elif op == '^' or op == '~':
                # Placeholder: Complex logic for ^ and ~ must be implemented here.
                continue
            elif op == '==':
                if v != target_v: return False
            elif op == '>=':
                if v < target_v: return False
            elif op == '>':
                if v <= target_v: return False
            elif op == '<=':
                if v > target_v: return False
            elif op == '<':
                if v >= target_v: return False
            elif op == '!=':
                if v == target_v: return False

        return True

    def __contains__(self, v: Version) -> bool:
        return self.contains(v)

    def __str__(self) -> str:
        # Return the original specification string, ensuring no whitespace is present as per requirement.
        return self._original_spec.replace(' ', '')

    def __repr__(self) -> str:
        return f"Range('{self._original_spec}')"

