                version_str = match.group(2).strip()

                if not version_str:
                    raise ValueError(f"Constraint '{cs}' has an empty version part.")

                try:
                    version = Version(version_str)
                    self.constraints.append((op, version))
                except ValueError as e:
                    raise ValueError(f"Bad version in constraint '{cs}': {e}")
