                # Handle exact version spec without operator (e.g., '1.2.3' implies '==1.2.3')
                try:
                    version = Version(cs)
                    self.constraints.append(('==', version))
                except ValueError:
                    raise ValueError(f"Unknown operator or bad format in constraint: '{cs}'")

