                continue

            satisfies = False
            if op == '==':
                satisfies = version == target_version
            elif op == '!=':
                satisfies = version != target_version
            elif op == '>':
                satisfies = version > target_version
            elif op == '<':
                satisfies = version < target_version
            elif op == '>=':
                satisfies = version >= target_version
            elif op == '<=':
