                if target_version.patch > 0:
                    upper_bound = Version(f"{target_version.major}.{target_version.minor + 1}.0")
                elif target_version.minor > 0:
                    upper_bound = Version(f"{target_version.major}.{target_version.minor}.{target_version.patch + 1}")
                else: # 0.0.0 case
                    upper_bound = Version("0.0.1")

                satisfies = (version >= target_version) and (version < upper_bound)

            if not satisfies:
                return False

        return True

    def __contains__(self, version: Version) -> bool:
        return self.contains(version)

    def __str__(self) -> str:
        # Reconstruct the spec string, removing internal whitespace
        return self.raw_spec.replace(' ', '').replace('\', '')

