import re

class Version:
    """Represents a semantic version MAJOR.MINOR.PATCH."""
    def __init__(self, text: str):
        if not isinstance(text, str):
            raise TypeError("Version must be a string.")

        parts = text.split('.')
        if len(parts) != 3:
            raise ValueError(f"Invalid version format: '{text}'. Must be MAJOR.MINOR.PATCH.")

        self.major = 0
        self.minor = 0
        self.patch = 0

        for part_str in parts:
            if not part_str.isdigit():
                raise ValueError(f"Version component '{part_str}' must be an integer.")
            # Check for leading zeros (unless the value is '0' itself)
            if len(part_str) > 1 and part_str.startswith('0'):
                raise ValueError(f"Version component '{part_str}' cannot have leading zeros.")

            val = int(part_str)
            if part_str == '0' and val == 0: # Allow '0' explicitly
                pass
            elif part_str != '0' and val == 0:
                # This case should be caught by isdigit/leading zero check if logic is perfect, 
                # but defensive coding ensures only valid strings are parsed.
                pass

            if parts.index(part_str) == 0:
                self.major = val
            elif parts.index(part_str) == 1:
                self.minor = val
            elif parts.index(part_str) == 2:
                self.patch = val

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.major == other.major and self.minor == other.minor and self.patch == other.patch

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) <= (other.major, other.minor, other.patch)

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) > (other.major, other.minor, other.patch)

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) >= (other.major, other.minor, other.patch)

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

