from typing import Dict, Optional, Any
from resolve.versions import Version, Range

class PackageIndex:
    """Stores all known package versions and their dependencies."""
    def __init__(self):
        # Structure: {package_name: {Version_object: {dependency_name: Range_object, ...}}} 
        self._packages: Dict[str, Dict[Version, Dict[str, Range]]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None):
        """Adds a release to the index."""
        try:
            version = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Bad version specified for {name}: {e}")

        if name not in self._packages:
            self._packages[name] = {}

        if version in self._packages[name]:
            raise ValueError(f"Duplicate release for {name} version {version} already exists.")

        # Convert string requirements to Range objects
        parsed_requires: Dict[str, Range] = {}
        if requires:
            for dep_name, spec_str in requires.items():
                try:
                    # Assuming Range constructor takes spec string
                    parsed_requires[dep_name] = Range(spec_str)
                except ValueError as e:
                    raise ValueError(f"Bad spec for dependency {dep_name} of {name}: {e}")

        self._packages[name][version] = parsed_requires

    def versions(self, name: str) -> list[Version]:
        """Returns the list of known Versions of name, newest first."""
        if name not in self._packages:
            return []

        versions_map = self._packages[name]
        # Sort by version object's inherent comparison (__gt__, __lt__)
        # We want newest first, so sort descending
        sorted_versions = sorted(versions_map.keys(), reverse=True)
        return sorted_versions

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        """Returns a dict mapping each dependency name to its Range for a given Version."""
        if name not in self._packages:
            raise KeyError(f"Package {name} not found in index.")

        if version not in self._packages[name]:
            raise KeyError(f"Version {version} of package {name} not found in index.")

        return self._packages[name][version]

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'PackageIndex':
        """Builds an index from the structured dictionary data."""
        instance = cls()
        for name, version_map in data.items():
            if name not in instance._packages:
                instance._packages[name] = {}

            for version_str, reqs_dict in version_map.items():
                try:
                    version = Version(version_str)
                except ValueError as e:
                    # Skip or raise, depending on strictness. Raising for robustness.
                    raise ValueError(f"Failed to parse version '{version_str}' for {name}: {e}")

                parsed_requires: Dict[str, Range] = {}
                for dep_name, spec_str in reqs_dict.items():
                    try:
                        # Assuming Range constructor takes spec string
                        parsed_requires[dep_name] = Range(spec_str)
                    except ValueError as e:
                        raise ValueError(f"Failed to parse spec for {dep_name} of {name}@{version}: {e}")

                instance._packages[name][version] = parsed_requires

        return instance

import re

class Version:
    """Represents a semantic version MAJOR.MINOR.PATCH."""
    def __init__(self, text: str):
        if not isinstance(text, str):
            raise TypeError("Version must be a string.")

        parts = text.split('.')
        if len(parts) != 3:
