class Range:
    """Represents a package version range constraint."""
    def __init__(self, spec: str):
        self.constraints = []
        self.raw_spec = spec
        self._parse_spec(spec)

    def _parse_spec(self, spec: str):
        if not spec.strip():
            raise ValueError("Empty spec provided.")

        # Split by comma, ignoring surrounding whitespace
        constraint_strs = [c.strip() for c in spec.split(',') if c.strip()]

        for cs in constraint_strs:
            if cs == "*":
                self.constraints.append(('any', None))
                continue

            # Regex to capture operator and version string. \* is reserved.
            # Operators: ==, !=, >=, <=, >, <, ^, ~
            match = re.match(r"^(==|!=|>=|<=|>|<|\^|~)(.*)$", cs)

            if match:
                op = match.group(1)
                version_str = match.group(2).strip()

                if not version_str:
                    raise ValueError(f"Constraint '{cs}' has an empty version part.")

                try:
                    version = Version(version_str)
                    self.constraints.append((op, version))
                except ValueError as e:
                    raise ValueError(f"Bad version in constraint '{cs}': {e}")
            else:
                # Handle exact version spec without operator (e.g., '1.2.3' implies '==1.2.3')
                try:
                    version = Version(cs)
                    self.constraints.append(('==', version))
                except ValueError:
                    raise ValueError(f"Unknown operator or bad format in constraint: '{cs}'")

    def contains(self, version: Version) -> bool:
        for op, target_version in self.constraints:
            if op == 'any':
                continue

            satisfies = False
            if op == '==':
                satisfies = version == target_version
            elif op == '!=':
                satisfies = version != target_version
            elif op == '>':
                satisfies = version > target_version
            elif op == '<':
                satisfies = version < target_version
            elif op == '>=':
                satisfies = version >= target_version
            elif op == '<=':
                satisfies = version <= target_version
            elif op == '^':
                # Caret range logic
                if target_version.major > 0:
                    upper_bound = Version(f"{target_version.major + 1}.0.0")
                    satisfies = (version >= target_version) and (version < upper_bound)
                elif target_version.minor > 0:
                    upper_bound = Version(f"{target_version.major}.{target_version.minor + 1}.0")
                    satisfies = (version >= target_version) and (version < upper_bound)
                elif target_version.patch > 0:
                    upper_bound = Version(f"{target_version.major}.{target_version.minor}.{target_version.patch + 1}")
                    satisfies = (version >= target_version) and (version < upper_bound)
                else: # 0.0.0 case
                    upper_bound = Version("0.0.1")
                    satisfies = (version >= target_version) and (version < upper_bound)
            elif op == '~':
                # Tilde range logic: >=V and <next_minor_release
                if target_version.patch > 0:
                    upper_bound = Version(f"{target_version.major}.{target_version.minor + 1}.0")
                elif target_version.minor > 0:
                    upper_bound = Version(f"{target_version.major}.{target_version.minor}.{target_version.patch + 1}")
                else: # 0.0.0 case
                    upper_bound = Version("0.0.1")

                satisfies = (version >= target_version) and (version < upper_bound)

            if not satisfies:
                return False

        return True

    def __contains__(self, version: Version) -> bool:
        return self.contains(version)

    def __str__(self) -> str:
        # Reconstruct the spec string, removing internal whitespace
        return self.raw_spec.replace(' ', '').replace('\', '')

def parse_line(line: str, fmt: str = 'auto') -> tuple[dict, ParseError | None]:
    """Directs a line to the appropriate parser based on format.

    Args:
        line: The raw string line from the log file.
        fmt: The expected format ('clf', 'jsonl', 'auto').

    Returns:
        A tuple containing the raw field dictionary and an error object if parsing fails.
    """
    if fmt == 'clf':
        try:
            raw_fields = parse_clf(line)
            return raw_fields, None
        except ParseError as e:
            return {}, e
    elif fmt == 'jsonl':
        try:
            # parse_jsonl returns a raw tuple, convert to dict for normalization compatibility
            ts_str, client, method, path, status, size, latency_ms = parse_jsonl(line)
            raw_fields = {
                'ts': ts_str, 
                'client': client, 
                'method': method, 
                'path': path, 
                'status': status, 
                'size': size, 
                'latency_ms': latency_ms
            }
            return raw_fields, None
        except ParseError as e:
            return {}, e
    elif fmt == 'auto':
        stripped_line = line.lstrip()
        if stripped_line.startswith('{'):
            # Auto-detects JSONL
            return parse_line(line, fmt='jsonl')
        else:
            # Auto-detects CLF
            return parse_line(line, fmt='clf')
    else:
        raise ValueError(f"Invalid format specified: {fmt}")

def read_records(lines: Iterable[str], fmt: str = 'auto') -> Tuple[List[Record], List[int]]:
    """Processes an iterable of lines, returning parsed records and a list of bad line numbers.

    Args:
        lines: An iterable of lines from the log file(s).
        fmt: The parsing format ('clf', 'jsonl', 'auto').

    Returns:
        A tuple: (list of successful Record objects, list of 1-based line numbers that failed).
    """
    records: List[Record] = []
    bad_lines: List[int] = []

    for line_num, line in enumerate(lines, 1):
        line = line.strip()
        if not line:  # Skip empty or whitespace-only lines
            continue

        raw_fields, error = parse_line(line, fmt) 

        if error:
            # Only record line numbers that raised ParseError
            bad_lines.append(line_num)
        else:
            try:
                # Normalize the raw fields into a canonical Record
                record = normalize(raw_fields)
                records.append(record)
            except ParseError as e:
                # This handles errors during normalization, which are also parsing errors
                bad_lines.append(line_num)

    return records, bad_lines
